from pathlib import Path
from html import escape
import json
out=Path('verification/mobile-menu-20261016')
items=[('monthly-menu','Dropdown directly under bookkeeping, stays open'),('blog','Centered Blog title, date and description'),('blog-support','Blog support button and explanation'),('home-support','Home support button'),('about-spacing','Reduced spacing above support button'),('index-hy','Space below the language selector'),('services-hy','Long Services labels stack above their button')]
s='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paper Trail mobile menu and Blog review</title><style>body{font:16px/1.6 Arial,sans-serif;color:#202020;background:#f3f3f3;margin:0}main{max-width:1100px;margin:auto;padding:25px}a{color:inherit}nav{display:flex;gap:16px;flex-wrap:wrap}button{padding:10px 18px;border:1px solid #202020;font:inherit;background:white;cursor:pointer}button[aria-pressed=true]{background:#202020;color:#fff}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:25px}figure{background:#fff;padding:16px;border:1px solid #ccc;margin:0}figcaption{font-weight:bold;margin-bottom:15px}img{display:block;width:390px;max-width:100%;height:auto;margin:auto}@media(max-width:700px){.gallery{grid-template-columns:1fr}}</style></head><body><main><h1>Mobile menu and Blog corrections</h1><nav><a href="../../index.html">Open Home</a><a href="../../blog.html">Open Blog</a><a href="../../past-due-bookkeeping.html">Try the mobile dropdown</a></nav><p>The dropdown starts directly below the bookkeeping row, remains open while selecting a destination, and keeps the page heading below the panel. Real touch taps reached Monthly Financial Reports at 320, 390 and 430 pixels.</p><p>Blog titles, dates and previews are centered on phones. Home uses Get Bookkeeping Support, and Blog has a localized support description and Contact link. Language notices have more space below the selector. Services headings stack above their buttons when the translated text would collide. The large gap above the About support button is reduced.</p><p>Passed 30 page and width checks, 60 language checks and three real touch navigation checks. No observed overflow, missing images or JavaScript exceptions. Desktop and iPad layouts are preserved. No Google API calls, form submissions, commits, pushes or publication.</p><nav aria-label="Phone width"><button data-width="320" aria-pressed="false">Small phone</button><button data-width="390" aria-pressed="true">Phone</button><button data-width="430" aria-pressed="false">Large phone</button></nav><div class="gallery">'''
for name,label in items:
 if name=='home-support':
  s+='<figure><figcaption>'+escape(label)+'</figcaption><a href="screenshots/home-support-390.png"><img src="screenshots/home-support-390.png" alt="'+escape(label)+'" loading="lazy"></a></figure>'
 else:s+='<figure><figcaption>'+escape(label)+'</figcaption><a data-shot="'+name+'" href="screenshots/'+name+'-390.png"><img data-shot="'+name+'" src="screenshots/'+name+'-390.png" alt="'+escape(label)+'" loading="lazy"></a></figure>'
s+='''</div><script>document.querySelectorAll('[data-width]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-width]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-shot]').forEach(e=>{e[e.tagName==='IMG'?'src':'href']='screenshots/'+e.dataset.shot+'-'+b.dataset.width+'.png';if(e.tagName==='IMG')e.style.width=b.dataset.width+'px'})})</script></main></body></html>'''
(out/'review.html').write_text(s,encoding='utf-8')
# Check every displayed screenshot exists before sharing the gallery.
import re
missing=[v for v in re.findall(r'<img[^>]*src="([^"]+)"',s) if not (out/v).is_file()]
assert not missing,missing
print('Screenshot review ready.')
